        next_loader = None
        meta = payload.get("meta")
        if isinstance(meta, dict) and ("current_page" in meta or "last_page" in meta):
            current, last = meta.get("current_page"), meta.get("last_page")
            if (
                not isinstance(current, int)
                or isinstance(current, bool)
                or not isinstance(last, int)
                or current < 1
                or last < current
            ):
                raise SerializationError("Invalid page-number pagination metadata")
        if isinstance(meta, dict) and meta.get("current_page", 0) < meta.get(
            "last_page", 0
        ):
            next_params = dict(params or {})
            next_params["page"] = int(meta["current_page"]) + 1
            seen = set(_seen_pages or ())
            if next_params["page"] in seen:
                raise SerializationError("Pagination page cycle detected")
            seen.add(next_params["page"])

            async def next_loader() -> AsyncPage[T]:
                return await self.request_page(
                    model=model, params=next_params, _seen_pages=seen, **kwargs
                )

        if isinstance(meta, dict) and meta.get("next_cursor") is not None:
            cursor = meta["next_cursor"]
            if not isinstance(cursor, str) or not cursor:
                raise SerializationError("Invalid pagination cursor")
            seen = set(_seen_pages or ())
            if cursor in seen or cursor == (params or {}).get("cursor"):
                raise SerializationError("Pagination cursor cycle detected")
            seen.add(cursor)
            next_params = {**(params or {}), "cursor": cursor}
            next_loader = lambda: self.request_page(
                model=model, params=next_params, _seen_pages=seen, **kwargs
            )
        return AsyncPage(items, payload.get("links"), meta, next_loader)
